export const heroSvg = "<svg class=\"art\" viewBox=\"0 0 1280 470\" role=\"img\" aria-label=\"Rack safety culture shown as a structure: three pillars — training, accountability and continuous improvement — carrying the roof of rack safety culture, resting on a base of leadership setting the tone\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect width=\"1280\" height=\"470\" fill=\"#0B1016\"/>\n    <!-- roof / lintel -->\n    <rect x=\"250\" y=\"112\" width=\"780\" height=\"44\" rx=\"3\" fill=\"#C9D1DA\"/>\n    <rect x=\"250\" y=\"106\" width=\"780\" height=\"7\" rx=\"3\" fill=\"#FF6A00\"/>\n    <text x=\"640\" y=\"141\" text-anchor=\"middle\" font-family=\"Fraunces,serif\" font-size=\"23\" font-weight=\"600\" fill=\"#0B1016\" letter-spacing=\".5\">Rack Safety Culture</text>\n    <!-- columns -->\n    <g>\n      <!-- capitals + shafts + bases -->\n      <g fill=\"#C9D1DA\">\n        <rect x=\"333\" y=\"160\" width=\"104\" height=\"14\" rx=\"2\"/><rect x=\"588\" y=\"160\" width=\"104\" height=\"14\" rx=\"2\"/><rect x=\"843\" y=\"160\" width=\"104\" height=\"14\" rx=\"2\"/>\n        <rect x=\"350\" y=\"174\" width=\"70\" height=\"188\" fill=\"#C9D1DA\"/><rect x=\"605\" y=\"174\" width=\"70\" height=\"188\" fill=\"#C9D1DA\"/><rect x=\"860\" y=\"174\" width=\"70\" height=\"188\" fill=\"#C9D1DA\"/>\n        <rect x=\"333\" y=\"362\" width=\"104\" height=\"14\" rx=\"2\"/><rect x=\"588\" y=\"362\" width=\"104\" height=\"14\" rx=\"2\"/><rect x=\"843\" y=\"362\" width=\"104\" height=\"14\" rx=\"2\"/>\n      </g>\n      <!-- fluting -->\n      <g stroke=\"#C9D1DA\" stroke-width=\"2\" opacity=\".5\"><line x1=\"373\" y1=\"176\" x2=\"373\" y2=\"360\"/><line x1=\"397\" y1=\"176\" x2=\"397\" y2=\"360\"/><line x1=\"628\" y1=\"176\" x2=\"628\" y2=\"360\"/><line x1=\"652\" y1=\"176\" x2=\"652\" y2=\"360\"/><line x1=\"883\" y1=\"176\" x2=\"883\" y2=\"360\"/><line x1=\"907\" y1=\"176\" x2=\"907\" y2=\"360\"/></g>\n    </g>\n    <!-- base -->\n    <rect x=\"270\" y=\"380\" width=\"740\" height=\"34\" rx=\"3\" fill=\"#E6EAEE\"/>\n    <text x=\"640\" y=\"402\" text-anchor=\"middle\" font-family=\"IBM Plex Mono,monospace\" font-size=\"13\" font-weight=\"600\" letter-spacing=\"2\" fill=\"#4D5A69\">LEADERSHIP SETS THE TONE</text>\n    <!-- column labels -->\n    <g font-family=\"IBM Plex Mono,monospace\" font-size=\"14\" font-weight=\"600\" fill=\"#C9D1DA\" text-anchor=\"middle\" letter-spacing=\"1\">\n      <text x=\"385\" y=\"445\">TRAINING</text>\n      <text x=\"640\" y=\"445\">ACCOUNTABILITY</text>\n      <text x=\"895\" y=\"445\">CONTINUOUS IMPROVEMENT</text>\n    </g>\n  </svg>";
export const html = "<p class=\"lead\" id=\"why\">Safety conversations usually start with compliance — audits, forms, inspection reports. But if safety is reduced to a checklist, it will always lag behind operations.</p>\n    <p>Top-performing organisations understand that real safety is <strong>cultural</strong>: leadership sets the tone, operations embed accountability, and frontline teams own the details. Rack safety — often overshadowed by forklift tracking and throughput KPIs — directly affects uptime, insurance risk, workforce morale and brand reputation, yet it’s still treated as a back-end function in many facilities.</p>\n    <p>For a CEO, COO, warehouse manager or investor, rack safety culture is more than a technical topic — it’s a strategic enabler of resilience, customer trust and scale. And it starts with what happens <em>between</em> inspections: how decisions are made, how people act when no one is watching, and how the organisation responds when a defect is found. Not fear, not rules — awareness, responsibility, and systems for continuous learning.</p>\n\n    <h2 id=\"pillars\">The three pillars of a rack safety culture</h2>\n    <h3>1 · Training that sticks</h3>\n    <ul class=\"clean\">\n      <li>Every team member should know what damage looks like, how to report it, and what not to ignore.</li>\n      <li>New-employee onboarding must include rack safety orientation.</li>\n      <li>Regular refreshers for forklift operators and shift leads reinforce vigilance.</li>\n      <li>Simple visual charts and short video refreshers keep the knowledge accessible.</li>\n    </ul>\n    <h3>2 · Accountability at all levels</h3>\n    <ul class=\"clean\">\n      <li>Appoint a <strong>PRSES</strong> (Person Responsible for Storage Equipment Safety) per EN 15635.</li>\n      <li>Display open findings with colour tags where teams can see them.</li>\n      <li>Use digital tools to track unclosed Red/Amber items and escalate them automatically.</li>\n      <li>Make sure findings aren’t just reported — they’re acted on.</li>\n    </ul>\n    <h3>3 · A continuous-improvement loop</h3>\n    <ul class=\"clean\">\n      <li>Keep inspection records and review the trends regularly.</li>\n      <li>Track repeat issues — is the same upright getting bent again?</li>\n      <li>Learn from near-misses and damage incidents.</li>\n      <li>Use safety dashboards to set measurable targets and watch the closure rate.</li>\n    </ul>\n\n    <h2 id=\"loop\">The improvement loop</h2>\n    <p>Pillar three is a cycle, not a one-off — each inspection feeds the next, and the same data that records a problem also reveals the pattern behind it.</p>\n    <figure>\n      <svg class=\"art\" viewBox=\"0 0 900 250\" role=\"img\" aria-label=\"The continuous improvement loop: record findings, review trends, spot repeat issues, learn from near-misses, set targets and close out — then repeat\" xmlns=\"http://www.w3.org/2000/svg\">\n        <rect width=\"900\" height=\"250\" fill=\"#0B1016\"/>\n        <g font-family=\"IBM Plex Sans,sans-serif\">\n          <g><rect x=\"15\" y=\"60\" width=\"156\" height=\"54\" rx=\"10\" fill=\"#C9D1DA\"/><text x=\"93\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#0B1016\">Record</text></g>\n          <g><rect x=\"192\" y=\"60\" width=\"156\" height=\"54\" rx=\"10\" fill=\"#C9D1DA\"/><text x=\"270\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#0B1016\">Review trends</text></g>\n          <g><rect x=\"369\" y=\"60\" width=\"156\" height=\"54\" rx=\"10\" fill=\"#C9D1DA\"/><text x=\"447\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#0B1016\">Spot repeats</text></g>\n          <g><rect x=\"546\" y=\"60\" width=\"156\" height=\"54\" rx=\"10\" fill=\"#C9D1DA\"/><text x=\"624\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#0B1016\">Learn</text></g>\n          <g><rect x=\"723\" y=\"60\" width=\"156\" height=\"54\" rx=\"10\" fill=\"#54DE91\"/><text x=\"801\" y=\"88\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#0B1016\">Target &amp;</text><text x=\"801\" y=\"105\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#0B1016\">close</text></g>\n          <g fill=\"#54DE91\"><polygon points=\"187,87 173,79 173,95\"/><polygon points=\"364,87 350,79 350,95\"/><polygon points=\"541,87 527,79 527,95\"/><polygon points=\"718,87 704,79 704,95\"/></g>\n          <!-- return loop -->\n          <path d=\"M801 114 L801 175 Q801 200 776 200 L118 200 Q93 200 93 175 L93 114\" fill=\"none\" stroke=\"#54DE91\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\" marker-end=\"url(#lp)\"/>\n          <text x=\"447\" y=\"222\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2BCB74\" font-weight=\"600\">…and the loop repeats — every inspection sharpens the next</text>\n          <defs><marker id=\"lp\" markerWidth=\"10\" markerHeight=\"10\" refX=\"5\" refY=\"2\" orient=\"auto\"><polygon points=\"0,8 5,0 10,8\" fill=\"#54DE91\"/></marker></defs>\n        </g>\n      </svg>\n      <figcaption>Record → review → spot repeats → learn → target and close — then round again.</figcaption>\n    </figure>\n\n    <h2 id=\"gaps\">The gaps that cost — and what good looks like</h2>\n    <table class=\"tbl\">\n      <tr><th>The culture gap</th><th>What good looks like</th></tr>\n      <tr><td class=\"m\">“Someone else will report it”</td><td class=\"r\">Operators stop and report bent bracing even when it isn’t inspection day.</td></tr>\n      <tr><td class=\"m\">“Safety ownership ended at the OEM handover”</td><td class=\"r\">The operator owns safe use, every day the rack is in service.</td></tr>\n      <tr><td class=\"m\">Reports filed but never reviewed</td><td class=\"r\">Audit summaries are part of shift briefings and monthly ops reviews.</td></tr>\n      <tr><td class=\"m\">A Red tag sits for weeks</td><td class=\"r\">Supervisors act within hours of a Red-tag issue.</td></tr>\n      <tr><td class=\"m\">No refreshers for contractors or new operators</td><td class=\"r\">Everyone on the floor is trained and kept current.</td></tr>\n      <tr><td class=\"m\">Closure isn’t tracked</td><td class=\"r\">Closure rates are reviewed as seriously as on-time dispatch.</td></tr>\n    </table>\n    <p class=\"pquote\">When rack safety becomes part of daily decision-making — that’s culture.</p>\n\n    <h2 id=\"rams\">How RAMS reinforces the culture</h2>\n    <ul class=\"clean\">\n      <li>Digitally tags issues and reminds the right people until they’re closed.</li>\n      <li>Dashboards make unclosed risks visible to management.</li>\n      <li>QR codes on uprights show the damage history for every location.</li>\n      <li>Tracks inspection performance by shift, facility or operator.</li>\n      <li>Optional in-app safety training and videos keep the culture alive.</li>\n    </ul>\n\n    <h2 id=\"payoff\">Culture is the strongest shield</h2>\n    <p>You can’t inspect your way out of a poor safety culture. When safety becomes a leadership priority — not just an operational one — the whole organisation aligns around it, and the payoff shows up across the business:</p>\n    <ul class=\"clean\">\n      <li>Fewer disruptions.</li>\n      <li>Reduced repair and replacement costs.</li>\n      <li>Lower insurance exposure.</li>\n      <li>Stronger compliance standing.</li>\n      <li>Higher employee trust and morale.</li>\n    </ul>\n    <p>Where downtime is expensive and reputational risk is high, culture is the most sustainable safety system you can build. RAMS helps leadership teams not just inspect, but embed safety as a daily, visible, data-driven habit.</p>\n\n    <div class=\"cta\">\n      <h3>Ready to build your safety culture?</h3>\n      <p>Let’s put a system of training, transparency and accountability around your racks.</p>\n      <a class=\"btn\" href=\"/company/contact\">Start the conversation</a>\n    </div>";
